import{z as i,x as B,o as e,c as p,q as r,j as n,D as E,d as A,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"RAG 中的上下文压缩","description":"","frontmatter":{"title":"RAG 中的上下文压缩","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-context-compression.md","filePath":"llm/rag-context-compression.md","lastUpdated":1791063341000}'),d={name:"llm/rag-context-compression.md"};function m(D,a,T,c,h,u){const o=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="rag-中的上下文压缩" tabindex="-1">RAG 中的上下文压缩 <a class="header-anchor" href="#rag-中的上下文压缩" aria-label="Permalink to &quot;RAG 中的上下文压缩&quot;">​</a></h1><div class="epigraph"><p>Top-k 块里只有几句在支撑答案，其余占窗口、占注意力、诱使胡编。压缩的是证据，不是把提示缩成口号。</p><footer>—— 对照 LLMLingua 一类提示压缩；RECOMP 一类针对检索块的压缩</footer></div><p><a href="/llm/adaptive-rag">上一课</a>决定检索之后，窗口仍可能被 \\(k\\) 块填满。主干已有<a href="/llm/prompt-compression">提示压缩</a>与检索式压缩；本课钉 RAG 场景：在<strong>保支撑</strong>的前提下缩短。缺口不是再讲 tokenizer，而是压缩与归因的冲突——删掉的句子可能正是引用对象。后课 ANN 结构默认：召回的候选可以多，送进阅读器的 token 必须少。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>压缩器若只优化语言建模困惑度，会留下流畅套话、删掉数字与约束。RAG 需要的是查询条件下的抽取或摘要：留下能支撑答案的句。Xu 等 RECOMP 训练压缩器服务下游 QA。LLMLingua 更偏通用提示压缩，用于 RAG 时必须用任务分数验收，不能只看压缩率。</p><p><span class="marginnote">术语翻译：困惑度（PPL）衡量「模型读到这段文字有多不意外」——写得顺、像八股的句子困惑度低，但未必有信息量。只按困惑度挑句子的压缩器，会专门保留「综上所述」式的空话，而把「赔偿上限为合同金额的 30%」这种关键数字当噪音删掉。</span></p><p>压缩后再引用：ID 必须仍指向未压缩块或可逆片段，否则归因课的可解析率崩掉。</p><p><span class="marginnote">把压缩交给阅读器自己「先看目录」而不删 token，是注意力税，不是压缩。真压缩要减少进入 softmax 的 token。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两种：抽取式（选句，可逆、好引用）与生成式摘要（更短、可能不忠）。先抽取后摘要。保留查询词命中句与高 BM25 句作下限。评测：压缩率、忠实度、答案正确、引用可解析。与切分重叠一起调：先切好再压，比先压整页再切更可控。</p><p><span class="marginnote">数字实例：Top-5 块、每块 500 token，窗口里就有 2500 token；真正支撑答案的可能只有 5 句、约 200 token。压到 1/5 不仅直接省下八成输入费用，还把阅读器的注意力从「九成噪音」里解放出来——压缩率和答案质量在这里是同一件事。</span></p>',11)),(e(),n(s,null,{default:E(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E6%A3%80%E7%B4%A2%E5%9D%97%22%5D%20--%3E%20EXT%5B%22%E6%8A%BD%E5%8F%96%E5%85%B3%E9%94%AE%E5%8F%A5%22%5D%0A%20%20EXT%20--%3E%20SUM%5B%22%E5%8F%AF%E9%80%89%E6%91%98%E8%A6%81%22%5D%0A%20%20SUM%20--%3E%20READ%5B%22%E9%98%85%E8%AF%BB%E5%99%A8%22%5D%0A%20%20EXT%20--%3E%20CIT%5B%22%E5%BC%95%E7%94%A8%E4%BB%8D%E6%8C%87%E5%90%91%E5%8E%9F%E5%9D%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"窗口里的无关句成为干扰负例，注意力与参数记忆都会被带偏，忠实度下降。压缩是在测试时做一次信息瓶颈，逼迫阅读器只看见高相关子集。瓶颈若由未校准的 LLM 摘要实现，会引入新幻觉层——必须用支撑指标挡。",-1)),(e(),n(s,null,{default:E(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOPK%5B%22Top-k%20%E6%A3%80%E7%B4%A2%E5%9D%97%22%5D%20--%3E%20MIX%5B%22%E6%94%AF%E6%92%91%E5%8F%A5%20%2B%20%E5%A4%A7%E9%87%8F%E6%97%A0%E5%85%B3%E5%A5%97%E8%AF%9D%E6%B7%B7%E5%9C%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20MIX%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%A2%AB%E8%B4%9F%E4%BE%8B%E5%88%86%E6%95%A3%22%5D%0A%20%20ATT%20--%3E%20HALLU%5B%22%E7%85%A7%E7%9D%80%E5%99%AA%E9%9F%B3%E8%A1%A5%E7%BB%86%E8%8A%82%2C%20%E5%BF%A0%E5%AE%9E%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20TOPK%20--%3E%20EXT%5B%22%E6%9F%A5%E8%AF%A2%E6%9D%A1%E4%BB%B6%E4%B8%8B%E6%8A%BD%E5%8F%96%E6%94%AF%E6%92%91%E5%8F%A5%22%5D%0A%20%20EXT%20--%3E%20CLEAN%5B%22%E7%AA%97%E5%8F%A3%E5%8F%AA%E5%89%A9%E9%AB%98%E7%9B%B8%E5%85%B3%E5%AD%90%E9%9B%86%22%5D%0A%20%20CLEAN%20--%3E%20FAITH%5B%22%E9%98%85%E8%AF%BB%E5%99%A8%E4%B8%93%E6%B3%A8%2C%20%E5%BF%A0%E5%AE%9E%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20EXT%20--%3E%20BACK%5B%22%E5%BC%95%E7%94%A8%20ID%20%E4%BB%8D%E6%8C%87%E5%9B%9E%E6%9C%AA%E5%8E%8B%E7%BC%A9%E5%8E%9F%E5%9D%97%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">为什么重要：压缩之后如果引用指到「被压掉的原文位置」，用户点开引用找不到那句话，产品可信度当场归零。可逆抽取（选句不改写）天然没这个问题；生成式摘要则必须额外存一份「摘要句 → 原块 ID」的映射。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>法律原文不可生成式压缩。下一课把「候选可以很多」交给 HNSW / IVF：那是索引层的近似，不是窗口层的压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAG 压缩保支撑与可引用，不以 PPL 或压缩率为第一指标。</li><li>抽取优于盲目摘要；引用指向原块。</li><li>用 QA 与忠实度验收，不用压缩率发版。</li><li>出处：RECOMP；LLMLingua；提示压缩课。</li></ul>',5))])}const f=i(d,[["render",m]]);export{_ as __pageData,f as default};
